impl Solution {
    pub fn add_negabinary(arr1: Vec<i32>, arr2: Vec<i32>) -> Vec<i32> {
        let mut sum = 0i64;
        let mut carry = 0i64;
        let mut result = Vec::new();

        // Process arr1
        for &digit in arr1.iter() {
            sum = carry + digit as i64;
            carry = sum / -2;
            result.push((sum % -2) as i32);
        }

        // Process arr2
        for &digit in arr2.iter() {
            sum = carry + digit as i64;
            carry = sum / -2;
            result.push((sum % -2) as i32);
        }

        // Process remaining carry
        while carry != 0 {
            sum = carry;
            carry = sum / -2;
            result.push((sum % -2) as i32);
        }

        // Remove leading zeros
        while result.len() > 1 && result[0] == 0 {
            result.remove(0);
        }

        result
    }
}

